#!/usr/bin/env python3
"""Rebuild TRAIN clause policy and development contrasts into a fresh directory."""
import argparse,json,hashlib,collections,re,time,sys
from pathlib import Path
parser=argparse.ArgumentParser()
parser.add_argument('--evidence-root',type=Path,required=True)
parser.add_argument('--output-dir',type=Path,required=True)
args=parser.parse_args();q=Path(__file__).resolve().parent;e=args.evidence_root;o=args.output_dir
o.mkdir(parents=True,exist_ok=False)
sys.path.insert(0,str(q));import evaluate_source_clauses as ev
root=json.load(open(e/'source-clause-root-attestations-r03.json'));lex=json.load(open(q/'reviewed-word-lexicon-en-sw-r02.json'));rules=json.load(open(q/'source-question-rules-r02.json'))
forms={'i like':('ninapenda','penda'),'i love':('ninapenda','penda'),'i want':('ninataka','taka'),'i need':('ninahitaji','hitaji'),'i know':('ninajua','jua'),'i think':('ninafikiri','fikiri'),'i enjoy':('ninafurahia','furahia'),'i live':('ninaishi','ishi'),'i work':('ninafanya kazi','fanya+kazi'),'i teach':('ninafundisha','fundisha'),'i have':('nina','na'),'do you have':('Je, una','na'),'do you like':('Je, unapenda','penda'),'do you want':('Je, unataka','taka'),'do you know':('Je, unajua','jua')}
counts=collections.Counter();tr=json.load(open(e/'bst-evaluation-source-r01/train.json'))
for d in tr:
 if d['context_dataset']!='convai2':continue
 for speaker,text in d['dialog']:
  if speaker:continue
  words=[m.group().casefold() for m in ev.candidates.__globals__['WORD'].finditer(text)]
  for source in forms:
   p=source.split();counts[source]+=sum(words[i:i+len(p)]==p for i in range(len(words)-len(p)+1))
entries=[]
for source,(target,stem) in forms.items():
 question=source.startswith('do you');row=dict(id='clause-en-sw-'+source.replace(' ','-'),source=source,target=target,person='second_singular_recipient' if question else 'first_singular',question=question,train_occurrences=counts[source],evidence_id=stem,meaning_review='Complete present-person predicate, with remaining source complement kept in English. No isolated-root slicing. Targets explicitly attested finite forms except separately documented possession/phrase composition.')
 if source.endswith(' have'):row['possession']=True
 if source=='i want':row['reject_right']=['for']
 if source=='i enjoy':row['reject_right']=['myself']
 if source=='i work':row['allow_right']=['at','in','from','for','as','during','part','full'];row['guard']='work_employment_or_task_context'
 if source=='i live':row['allow_right']=['in','near','with','at'];row['guard']='live_residence_context'
 entries.append(row)
policy=dict(schema='vipi-reviewed-source-clause-research-3',production=False,training_only=True,entries=entries,attestation=root,primary_grammar_sources=[dict(url='https://kiswahili.ku.edu/sites/kiswahili/files/documents/lessons/Lesson%201-10/all.pdf',scope='University teaching examples corroborate first-person present liking, work expression, and sentence-initial Je question framing. Facts verify authored units; no full course passages imported.'),dict(url='https://openbooks.library.baylor.edu/elementaryswahili1/chapter/lesson-3-una-umri-gani/',scope='Present possession contrasts nina and una; these are possession forms, not perfect auxiliaries.'),dict(url='https://openbooks.library.baylor.edu/elementaryswahili1/chapter/lesson-4-kutoka-na-kukaa-wapi/',scope='Primary course indexed text describes subject-prefix/present/stem formation; direct page fetch403 retained as access limitation.')],scope='Exact words contiguous, no external modal/do auxiliary; positive present I predicates. Question units only sentence-initial and one-to-one singular recipient assumed. Have requires bounded explicit nominal complement and qualified following boundary; perfect, obligation and causative forms are inapplicable.',limitations=['Local guards are not a complete grammar or word-sense parser.','Finite predicates with English complements intentionally remain mixed language; target object agreement is not solved.','Question units do not claim plural recipient support.','Source absence and ambiguity are evaluated, not filled with model calls.'])
(o/'reviewed-source-clauses-r03.json').write_text(json.dumps(policy,ensure_ascii=False,indent=2)+'\n')
cases=[('I like music.','i like',True),('I love dogs.','i love',True),('I want a car.','i want',True),('I need help.','i need',True),('I know.','i know',True),('I think so.','i think',True),('I enjoy cooking.','i enjoy',True),('I teach children.','i teach',True),('I live in Kenya.','i live',True),('I work at school.','i work',True),('I have a dog.','i have',True),('I have two dogs.','i have',True),('I have 3 dogs.','i have',True),('Do you have a cat?','do you have',True),('Do you like music?','do you like',True),('Do you want food?','do you want',True),('Do you know?','do you know',True),('I do not like music.','i like',False),("I don't need food.",'i need',False),('I would like a dog.','i like',False),('Would I like this?','i like',False),('Did I know you?','i know',False),('I liked it yesterday.','i like',False),('I have eaten.','i have',False),('I have been there.','i have',False),('I have to go.','i have',False),('I have my car repaired.','i have',False),('I have milk delivered.','i have',False),('I want for nothing.','i want',False),('I work out daily.','i work',False),('I live for music.','i live',False),('I enjoy myself.','i enjoy',False),('What music do you like?','do you like',False),('Which pets do you have?','do you have',False),('`I like music`','i like',False),('I? like music.','i like',False),('I. Have a dog.','i have',False),('We like music.','i like',False),('Do you all like music?','do you like',False)]
rows=[]
for text,source,expected in cases:
 tokens,_,_=ev.candidates(text,lex,rules);hits,rejects=ev.clause_candidates(text,tokens,lex,policy);actual=any(x['original'].casefold()==source for x in hits);rows.append(dict(text=text,source_unit=source,expected=expected,actual=actual,passed=expected==actual,accepted=hits,rejected=rejects))
assert all(x['passed'] for x in rows),[x for x in rows if not x['passed']]
(o/'source-clause-contrasts-r03.json').write_text(json.dumps(dict(development_only=True,production=False,rows=rows),ensure_ascii=False,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
freeze=dict(schema='vipi-source-clause-freeze-3',production=False,frozen_unix=time.time(),lexicon_sha256=sha(q/'reviewed-word-lexicon-en-sw-r02.json'),rules_sha256=sha(q/'source-question-rules-r02.json'),clauses_sha256=sha(o/'reviewed-source-clauses-r03.json'),evaluator_sha256=sha(q/'evaluate_source_clauses.py'),base_evaluator_sha256=sha(q/'evaluate_source_concepts.py'),development_contrast_sha256=sha(o/'source-clause-contrasts-r03.json'),clause_units=len(entries),clause_predicate_concepts=10,expected_benefit='Correct content depth and finite forms, not just one-word availability already credited to I. Frequency-first source units selected on TRAIN; no new reference sentences from held-out data.',selection='Complete content clauses before individual content words, then existing source unit priority. Primary is one unit;25% arm applies strict source-word budget. Whole exact clause credit separately recorded and preferred over a fragment for a full-match message.',new_holdout='80 new VALID free-human convai2 messages, 26/27/27 length strata, excluding all prior160 VALID dialogues and prior protocol text.',research_advance_only=dict(primary_clean_useful_at_least=72,primary_material_or_scope_errors_at_most=2,content_clean_useful_at_least=40),additional_effect_measure='Paired correct content depth and content-bearing messages versus frozen219-word/12-question-rule control; report availability failure even if depth improves.',scoring='Exact source scopes and outputs, selected-unit semantic review, independent24 fixed before outputs. Material sense/scope errors separate from minor grammar/uncertainty. New whole clauses reviewed, never automatic full-MT credit.',production_promotion=False)
(o/'source-clause-freeze-r03.json').write_text(json.dumps(freeze,ensure_ascii=False,indent=2)+'\n');print('contrasts',len(rows),'policy',sha(o/'reviewed-source-clauses-r03.json'),'freeze',sha(o/'source-clause-freeze-r03.json'));print(counts)
